import numpy as np
from itertools import product

def feats(blk):
    f = {}
    vals, cnts = np.unique(blk, return_counts=True)
    f['counts'] = dict(zip(vals.tolist(), cnts.tolist()))
    return f

def max_run(cells):
    # cells: list of (r,c); max straight contiguous run horiz or vert
    best = 0
    s = set(cells)
    for (r,c) in cells:
        for dr,dc in ((0,1),(1,0)):
            if (r-dr,c-dc) not in s:  # start of run
                L=0; rr,cc=r,c
                while (rr,cc) in s: L+=1; rr,cc=rr+dr,cc+dc
                best=max(best,L)
    return best

def comp_sizes(cells):
    s=set(cells); seen=set(); sizes=[]
    for c0 in cells:
        if c0 in seen: continue
        st=[c0]; comp=0
        while st:
            c=st.pop()
            if c in seen: continue
            seen.add(c); comp+=1
            r,cc=c
            for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                if (r+dr,cc+dc) in s and (r+dr,cc+dc) not in seen: st.append((r+dr,cc+dc))
        sizes.append(comp)
    return sorted(sizes)

